// @ts-check
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { basename, isAbsolute, join, resolve } from 'node:path';
import semver from 'semver';
import { docsUrl, normalizeLibraries } from './config.js';
import { BundleError } from './errors.js';
import { fetchLibrary, resolveVersion } from './fetch.js';
import { listDeclarations, readLibrary } from './library.js';
import { orderLibraries } from './order.js';

/**
 * @typedef {object} ResolvedLibrary
 * @property {string} name
 * @property {string} version
 * @property {string} sha Full commit SHA of the `dist/v<version>` tag.
 * @property {string} repository
 */

/**
 * @typedef {object} BundleResult
 * @property {string} code The bundle for `outFile`.
 * @property {string} types The declarations for `typesFile`.
 * @property {ResolvedLibrary[]} resolved Libraries in bundle order.
 */

/** @typedef {ResolvedLibrary & { dir: string, loadOrder: string[], peers: Record<string, string> }} Fetched */

const HEADER =
  '// Generated by gas-dev-config bundle — do not edit. Run `npx gas-dev-config bundle` to update.\n';

/** A `"use strict"` directive line, in either quote style. */
const USE_STRICT = /^(["'])use strict\1;$/;

/**
 * Drops `"use strict";` lines in either quote style; the bundle emits one directive at its top instead.
 *
 * @param {string} source
 * @returns {string} The source with a single trailing newline.
 */
function stripUseStrict(source) {
  const lines = source.split('\n').filter((line) => !USE_STRICT.test(line));
  return `${lines.join('\n').replace(/\n*$/, '')}\n`;
}

/**
 * @param {ResolvedLibrary[]} resolved
 * @returns {string}
 */
function header(resolved) {
  const lines = resolved.map(
    ({ name, version, sha, repository }) =>
      `// ${name} ${version} (${sha})\n//   ${docsUrl(repository, version)}\n`,
  );
  return `${HEADER}${lines.join('')}`;
}

/**
 * Throws when the code is not a syntactically valid script.
 *
 * @param {string} code
 * @throws {BundleError} With node's diagnostics.
 */
function checkSyntax(code) {
  const dir = mkdtempSync(join(tmpdir(), 'gas-dev-config-bundle-'));
  try {
    const file = join(dir, 'bundle.js');
    writeFileSync(file, code);
    const result = spawnSync(process.execPath, ['--check', file], {
      encoding: 'utf8',
    });
    if (result.status !== 0) {
      throw new BundleError(
        `The generated bundle has a syntax error:\n${result.stderr.trim()}`,
      );
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/**
 * Resolves, fetches and concatenates gas-* libraries into one global script. Writes nothing
 * outside the cache.
 *
 * @param {object} options
 * @param {Record<string, string | { version: string, repository?: string }>} options.libraries Same shape as `gasDevConfig.bundle.libraries`; may be empty.
 * @param {string} [options.cwd] Project root; default `process.cwd()`.
 * @param {string} [options.cacheDir] Default `<cwd>/node_modules/.cache/gas-dev-config/bundle`.
 * @param {string[]} [options.extraFiles] Absolute `.js` paths appended after the libraries, in order.
 * @param {(message: string) => void} [options.warn] Receives warnings; default writes to stderr.
 * @returns {BundleResult}
 * @throws {BundleError} On invalid input, git failures, invalid library metadata, cycles or syntax errors.
 */
export function bundle({
  libraries,
  cwd = process.cwd(),
  cacheDir = join(cwd, 'node_modules', '.cache', 'gas-dev-config', 'bundle'),
  extraFiles = [],
  warn = (message) => process.stderr.write(`${message}\n`),
}) {
  for (const file of extraFiles) {
    if (!isAbsolute(file)) {
      throw new BundleError(`extraFiles entry must be absolute: ${file}`);
    }
  }
  const configured = normalizeLibraries(libraries, 'libraries', true);

  /** @type {Map<string, Fetched>} */
  const fetched = new Map();
  for (const [name, { version: range, repository }] of Object.entries(
    configured,
  )) {
    const version = resolveVersion(name, range, repository);
    const { dir, sha } = fetchLibrary({
      name,
      version,
      repository,
      cacheDir: resolve(cacheDir),
    });
    fetched.set(name, {
      name,
      version,
      sha,
      repository,
      dir,
      ...readLibrary(name, dir),
    });
  }

  for (const library of fetched.values()) {
    for (const [peer, range] of Object.entries(library.peers)) {
      const found = fetched.get(peer);
      if (found && !semver.satisfies(found.version, range)) {
        warn(
          `gas-dev-config: warning: ${library.name} ${library.version} expects ${peer} ${range}, but ${peer} ${found.version} is bundled.`,
        );
      }
    }
  }

  const order = orderLibraries(
    [...fetched.keys()],
    Object.fromEntries(
      [...fetched.values()].map((library) => [
        library.name,
        Object.keys(library.peers).filter((peer) => fetched.has(peer)),
      ]),
    ),
  );
  const ordered = order.flatMap((name) => fetched.get(name) ?? []);
  const resolved = ordered.map(({ name, version, sha, repository }) => ({
    name,
    version,
    sha,
    repository,
  }));

  const codeBlocks = [];
  const typeBlocks = [];
  for (const library of ordered) {
    for (const file of library.loadOrder) {
      codeBlocks.push(
        block(
          `${library.name}/${file}`,
          readFileSync(join(library.dir, file), 'utf8'),
        ),
      );
    }
    for (const file of listDeclarations(library.dir)) {
      typeBlocks.push(
        block(
          `${library.name}/${file}`,
          readFileSync(join(library.dir, file), 'utf8'),
          false,
        ),
      );
    }
  }
  for (const file of extraFiles) {
    codeBlocks.push(block(basename(file), readFileSync(file, 'utf8')));
  }

  const head = header(resolved);
  const code = `${head}\n'use strict';\n\n${codeBlocks.join('\n')}`;
  checkSyntax(code);
  return { code, types: `${head}\n${typeBlocks.join('\n')}`, resolved };
}

/**
 * @param {string} label
 * @param {string} source
 * @param {boolean} [strict] Whether to strip `"use strict";` lines.
 * @returns {string}
 */
function block(label, source, strict = true) {
  const body = strict
    ? stripUseStrict(source)
    : `${source.replace(/\n*$/, '')}\n`;
  return `// ---- ${label} ----\n${body}`;
}
